import { api } from './api';
import type { Agent, Overview, Sparklines, ProbeResult, PublicMeta, VersionInfo } from './types';

export const publicApi = {
  overview: () => api.get<Overview>('/api/public/overview'),
  agents: () => api.get<Agent[]>('/api/public/agents'),
  agent: (id: string) => api.get<Agent>(`/api/public/agents/${encodeURIComponent(id)}`),
  sparklines: () => api.get<Sparklines>('/api/public/sparklines'),
  probes: (id: string) => api.get<ProbeResult[]>(`/api/public/agents/${encodeURIComponent(id)}/probes`),
  meta: () => api.get<PublicMeta>('/api/public/meta'),
  version: () => api.get<VersionInfo>('/api/public/version'),
};
